async function freeFireApi(action,payload={}){const res=await fetch(FREE_FIRE_API,{method:"POST",headers:{"Content-Type":"application/json","apikey":SUPABASE_KEY,"Authorization":"Bearer "+SUPABASE_KEY},body:JSON.stringify({action,...payload,session_token:session})});const data=await res.json().catch(()=>({error:"Server returned an invalid response."}));if(!res.ok)throw Error(data.error||"Free Fire request failed.");return data;}
async function loadFreeFire(){if(!session||freeFireData.loading)return;freeFireData.loading=true;freeFireData.error="";try{const data=await freeFireApi("status");freeFireData={...freeFireData,...data,spin:null,loading:false,loaded:true};if(!data.is_admin&&activePage==="ffadminhub"){activePage="home";localStorage.setItem("tm_active_page","home");}const inv=await freeFireApi("inventory_list");freeFireData.inventory=inv.items||[];freeFireData.categoryCounts=inv.counts||{};if(data.is_admin){const admin=await freeFireApi("admin_claims",{status:"all"});freeFireData.adminClaims=admin.claims||[];const invAdmin=await freeFireApi("inventory_admin_list");freeFireData.adminInventory=invAdmin.items||[];const wd=await withdrawalApi("admin_list",{status:"all"});tmWithdrawalData.adminRequests=wd.requests||[];}}catch(err){freeFireData.loading=false;freeFireData.loaded=true;freeFireData.error=err.message;}if(session)render();}async function loadFreeFireCatalog(offset=0){freeFireData.catalogLoading=true;freeFireData.error="";try{const page=await freeFireApi("inventory_list",{category:ffWizardCategory,offset,limit:60});freeFireData.inventory=page.items||[];freeFireData.catalogTotal=page.total||0;freeFireData.catalogOffset=page.offset||0;freeFireData.catalogLimit=page.limit||60;}catch(err){freeFireData.error=err.message;}finally{freeFireData.catalogLoading=false;render();}}
