function discoverPage(){
const current=discoverProfiles[0];
if(discoverLoading&&!current)return '<div class="page-heading"><p class="eyebrow">MEET YOUR PEOPLE</p><h1>Discover</h1><p class="lead">Finding people and connections for you…</p></div><div class="discover-loading"><span></span><span></span><span></span><p>Loading profiles</p></div>';
const matches=discoverMatches.length?'<section class="discover-matches"><div class="section-heading"><div><p class="eyebrow">MUTUAL CONNECTIONS</p><h2>Your matches</h2></div><span class="discover-match-count">'+discoverMatches.length+'</span></div><div class="discover-match-strip">'+discoverMatches.map(m=>'<button class="discover-match-chip" data-discover-match-open="'+safe(m.id)+'"><span class="discover-match-avatar">'+(m.other_user.photo_url?'<img src="'+safe(m.other_user.photo_url)+'" alt="">':safe((m.other_user.display_name||"T").slice(0,1)))+'</span><span><strong>'+safe(m.other_user.display_name)+'</strong><small>Open conversation</small></span></button>').join("")+'</div></section>':'';
const notices=discoverNotifications.filter(n=>!n.read_at).slice(0,3).map(n=>'<div class="discover-notification"><span>♥</span><div><strong>'+safe(n.title)+'</strong><small>'+safe(n.body)+'</small></div></div>').join("");
const profile=current?'<article class="discover-swipe-card" data-discover-swipe-card data-profile-id="'+safe(current.id)+'"><div class="discover-swipe-photo">'+(current.photo_url?'<img src="'+safe(current.photo_url)+'" alt="'+safe(current.display_name)+'" draggable="false">':'<div class="discover-initial">'+safe((current.display_name||"T").slice(0,1).toUpperCase())+'</div>')+'<span class="profile-status-dot '+(current.is_online?"online":"offline")+'" title="'+(current.is_online?"Online":"Offline")+'"></span><span class="discover-badge">'+safe(current.is_demo?"Demo preview":(current.plan||"Free"))+'</span><div class="discover-swipe-gradient"></div><div class="discover-swipe-title"><h2>'+safe(current.display_name||"TM member")+', '+safe(current.age||"")+'</h2><p>'+safe([current.city,current.country].filter(Boolean).join(", "))+'</p></div><span class="discover-swipe-stamp discover-stamp-no">NO</span><span class="discover-swipe-stamp discover-stamp-yes">YES</span></div><div class="discover-profile-details"><div class="discover-profile-meta"><span>'+safe(current.gender||"")+'</span><span>TM member · '+safe(current.plan||"Free")+'</span></div><p class="discover-bio">'+safe(current.bio||"Getting to know people on TM.")+'</p>'+(current.interests?.length?'<div class="discover-detail-group"><strong>Interests</strong><div class="discover-tags">'+current.interests.map(x=>'<span>'+safe(x)+'</span>').join("")+'</div></div>':'')+(current.looking_for?.length?'<div class="discover-detail-group"><strong>Looking for</strong><div class="discover-tags">'+current.looking_for.map(x=>'<span>'+safe(x)+'</span>').join("")+'</div></div>':'')+(current.preferred_partner?'<div class="discover-detail-group"><strong>Preferred partner</strong><p>'+safe(current.preferred_partner)+'</p></div>':'')+(current.flirt_style?'<div class="discover-detail-group"><strong>Connection style</strong><p>'+safe(current.flirt_style)+'</p></div>':'')+(current.languages?.length?'<div class="discover-detail-group"><strong>Languages</strong><div class="discover-tags">'+current.languages.map(x=>'<span>'+safe(x)+'</span>').join("")+'</div></div>':'')+(current.gallery_photo_urls?.length?'<div class="discover-gallery">'+current.gallery_photo_urls.slice(0,6).map(url=>'<img src="'+safe(url)+'" alt="Profile photo" loading="lazy">').join("")+'</div>':'')+'</div><div class="discover-swipe-actions"><button class="discover-message-button" data-discover-chat="'+safe(current.tm_number||"")+'" aria-label="Message" title="Message">'+icon("chats")+'</button><button class="discover-no-button" data-discover-decision="pass" data-profile-id="'+safe(current.id)+'" aria-label="Pass">×</button><span>Swipe left to pass · right to like</span><button class="discover-yes-button" data-discover-decision="like" data-profile-id="'+safe(current.id)+'" aria-label="Like">♥</button></div></article>':'<div class="discover-empty"><div>♥</div><h2>You’re all caught up</h2><p>There are no more profiles to show right now. Your matches will stay here.</p><button class="secondary-button" data-discover-refresh>Refresh profiles</button></div>';
return '<div class="page-heading"><p class="eyebrow">MEET YOUR PEOPLE</p><h1>Discover</h1><p class="lead">Real profiles. Mutual likes. Meaningful connections.</p></div>'+notices+matches+'<div class="discover-toolbar"><button class="secondary-button" data-discover-refresh>Refresh profiles</button></div>'+(discoverNotice?'<div class="discover-match-notice"><span>♥</span><div><strong>'+safe(discoverNotice)+'</strong><small>Your match is ready to chat. Find them in Your matches.</small></div><button data-discover-notice-close aria-label="Dismiss">×</button></div>':'')+'<div class="discover-deck">'+profile+'</div>';
}
function aiRoom(){const tools=[["face","🪄","Photo Face Swap","Swap faces in photos","Photo"],["video-face","🎬","Video Face Swap","Swap faces in video clips","Video"],["image","🖼️","AI Image Generator","Create images from a text prompt","Image"],["video","🎥","AI Video Generator","Turn ideas into short videos","Video"],["talking","🗣️","Talking Photo & Lip Sync","Animate a portrait with speech","Audio + photo"],["remove-bg","✂️","Background Remover","Remove image backgrounds","Image"],["upscale","✨","Image Enhancer","Improve image clarity and size","Image"],["workflow","🧩","AI Workflows","Combine creative tools","Workflow"],["editor","🛠️","Image Editor","Resize, rotate, flip and export photos","Image"],["convert","🗜️","Image Converter","Compress and convert JPG, PNG or WebP","Image"],["info","ⓘ","Image Details","Inspect image dimensions, format, size and transparency","Image"]];return '<div class="ai-studio-page"><header class="ai-studio-hero"><div class="ai-studio-brand"><span class="ai-studio-mark">✦</span><span>TM <b>AI</b></span><span class="ai-studio-label">CREATIVE STUDIO</span></div><p class="eyebrow">YOUR AI CREATIVE WORKSPACE</p><h1>Bring your ideas<br><span>to life.</span></h1><p class="lead">Explore AI-powered photo, video and creative tools in one place.</p><div class="ai-studio-chips"><span>✦ Free-first development</span><span>🔒 Your account stays yours</span><span>🔐 Provider keys are kept server-side</span></div></header><div class="ai-studio-heading"><div><p class="eyebrow">TOOLS</p><h2>What do you want to make?</h2><p>Select a tool to open its workspace.</p></div><span class="ai-tool-count">11 creative tools</span></div><div class="ai-studio-grid">'+tools.map(t=>'<button class="ai-studio-card" data-ai-tool="'+t[0]+'"><span class="ai-studio-card-icon">'+t[1]+'</span><span class="ai-studio-card-title">'+t[2]+'</span><span class="ai-studio-card-desc">'+t[3]+'</span><span class="ai-studio-card-bottom"><span>'+t[4]+'</span><span class="ai-studio-card-arrow">↗</span></span></button>').join("")+'</div><section class="ai-engine-notice"><span class="ai-engine-notice-icon">⚙</span><div><strong>AI gateway deployed · provider setup pending</strong><p>The secure TM AI gateway is deployed. Image generation is wired to Hugging Face but requires its server-side token. Video, face swap and talking-avatar providers remain disconnected until we verify free quotas and get your approval for any paid use.</p></div></section></div>';}



