const eventCards=events.length?events.map(x=>'<article class="duel-card duel-event-card">'+(x.flyer_url?'<img class="duel-event-flyer" loading="lazy" src="'+safe(x.flyer_url)+'" alt="Event flyer for '+safe(x.title)+'">':'')+'<div class="duel-card-top"><span class="duel-tag">FREE FIRE EVENT</span><small>'+duelDate(x.starts_at)+'</small></div><h3>'+safe(x.title)+'</h3><p>'+safe(x.description||x.challenge_mode||"Community event")+'</p><div class="duel-meta"><span>Hosted by '+duelHost(x)+'</span><span>'+x.member_count+' joined · '+x.capacity+' max</span></div><button class="duel-action" data-duel-action="join-event" data-id="'+x.id+'">JOIN EVENT</button>'+((x.host_user_id===accountUser?.id)?'<button class="duel-secondary duel-delete-event" data-duel-action="delete-event" data-id="'+x.id+'">DELETE EVENT</button>':'')+'</article>').join(""):'<p class="duel-empty">No events posted yet. Be the first to host one.</p>';
const challengeCards=challenges.length?challenges.map(x=>'<article class="duel-card"><div class="duel-card-top"><span class="duel-tag">'+safe(x.mode)+'</span><small>'+duelDate(x.starts_at)+'</small></div><h3>'+safe(x.title)+'</h3><p>'+safe(x.description||"Open challenge · prove your skill")+'</p><div class="duel-meta"><span>Hosted by '+duelHost(x)+'</span><span>'+x.member_count+' players</span></div><button class="duel-action" data-duel-action="join-challenge" data-id="'+x.id+'">ENTER CHALLENGE</button></article>').join(""):'<p class="duel-empty">No open challenges. Create the first match-up.</p>';
